//! The TS 26.442 ROM tables, generated by `reference/evs/oracle/gen_rom.sh`; do not edit.
//!
//! Each table keeps the reference's name, upper-cased. A pointer in a reference table becomes a
//! slice from the pointed-to element to the end of its target table; a null pointer becomes an
//! empty slice. `unsupported.txt` beside this file lists the tables not exported (function
//! pointers), which are ported by hand where they are used.

#![allow(
    clippy::unreadable_literal,
    clippy::excessive_precision,
    clippy::approx_constant
)]

/// `&slice[start..]`, usable in a static initializer.
pub const fn tail<T>(slice: &'static [T], start: usize) -> &'static [T] {
    slice.split_at(start).1
}

